"""Build the chosen poster-style six-page static website."""

from pathlib import Path
from shutil import copy2
import re

ROOT = Path(__file__).resolve().parent
SITE = ROOT / "hajnal-site"
SITE.mkdir(exist_ok=True)
(SITE / "assets").mkdir(exist_ok=True)

for asset in (ROOT / "assets").glob("*.webp"):
    copy2(asset, SITE / "assets" / asset.name)
copy2(ROOT / "assets" / "hajnal-sun.svg", SITE / "assets" / "hajnal-sun.svg")
copy2(ROOT / "assets" / "hajnal-sun-logo.svg", SITE / "assets" / "hajnal-sun-logo.svg")
copy2(ROOT.parent / "képek" / "15670084-uhd_1440_2560_30fps.mp4", SITE / "assets" / "hajnal-reggel.mp4")
copy2(ROOT.parent / "letoltheto" / "hajnal-kovaszos-receptek.pdf", SITE / "assets" / "hajnal-kovaszos-receptek.pdf")
copy2(ROOT / "style.css", SITE / "style.css")
copy2(ROOT / "site.js", SITE / "site.js")
copy2(ROOT / "pages.css", SITE / "pages.css")
copy2(ROOT / "pages.js", SITE / "pages.js")

prototype = (ROOT / "tervek" / "02-plakat" / "index.html").read_text(encoding="utf-8")

def without_button_arrows(html):
    def clean(match):
        button = re.sub(r'\s*<span aria-hidden="true">[↗↘↓]</span>', '', match.group(0))
        return re.sub(r'\s+[↗↘↓](?=</(?:a|button)>)', '', button)
    return re.sub(r'<(?:a|button)\b[^>]*class="[^"]*\bbutton\b[^"]*"[^>]*>.*?</(?:a|button)>', clean, html, flags=re.S)

def chrome(page):
    head = f'''<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{page['title']} | Hajnal Kovászos Pékség</title><meta name="description" content="{page['description']}"><link rel="icon" type="image/svg+xml" href="assets/hajnal-sun.svg"><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="pages.css"></head><body class="site-final page-{page['slug']}" id="top">'''
    header = re.search(r'(<a class="skip".*?</header>)', prototype, re.S).group(1)
    header = header.replace('href="#top"', 'href="index.html"').replace('href="#kinalat"', 'href="kinalat.html"').replace('href="#rolunk"', 'href="rolunk.html"').replace('href="#workshop"', 'href="workshop.html"').replace('href="#kapcsolat"', 'href="kapcsolat.html"').replace('href="#elorendeles"', 'href="elorendeles.html"')
    header = header.replace('<span>Pécs belvárosában</span>', '<span>Fiktív vizsgademó · Pécs</span>')
    header = re.sub(r'<a class="nav-cta".*?</a>', '', header)
    footer = re.search(r'(<footer class="footer".*?</footer>)', prototype, re.S).group(1)
    footer = footer.replace('Vasárnap–hétfő · zárva', 'Vasárnap–Hétfő · zárva').replace('Kedd–szombat', 'Kedd–Szombat')
    footer = footer.replace('<div class="foot-bottom">', '<div class="footer-legal"><a href="adatkezeles.html">Adatkezelési tájékoztató</a></div><div class="foot-bottom">')
    return head + header, footer + '<script src="site.js" defer></script><script src="pages.js" defer></script></body></html>'

def page(slug, title, description, content):
    start, end = chrome(dict(slug=slug, title=title, description=description))
    (SITE / f"{slug}.html").write_text(start + '<main id="tartalom">' + without_button_arrows(content) + '</main>' + end, encoding="utf-8")

home = re.search(r'(<main id="tartalom">.*?</main>)', prototype, re.S).group(1)
home = home.replace('../../assets/', 'assets/').replace('href="#kinalat"', 'href="kinalat.html"').replace('href="#rolunk"', 'href="rolunk.html"').replace('href="#workshop"', 'href="workshop.html"').replace('href="#kapcsolat"', 'href="kapcsolat.html"').replace('href="#elorendeles"', 'href="elorendeles.html"')
home = re.sub(r'<p class="prototype-note">.*?</p>', '', home)
home = home.replace('Nézd meg, hol veheted át', 'Előrendelést indítok').replace('href="kapcsolat.html">Előrendelést indítok', 'href="elorendeles.html">Előrendelést indítok')
home = home.replace('class="text-link"', 'class="button button-secondary"')
home = home.replace('class="button button-outline"', 'class="button button-secondary"')
home = re.sub(r'(<div class="offer-body">.*?<a) href=', r'\1 class="button button-secondary" href=', home, flags=re.S)
home = home.replace('Mikor találok nyitva?', 'Reggeliznék egy jót')
home = home.replace('Reggeliznék egy jót', 'Reggelizek egy jót').replace('Egész kenyeret rendelnék', 'Kenyeret rendelek').replace('Tortáról érdeklődöm', 'Tortát rendelek')
home = home.replace('✳ PÉCS ✳', 'A HAJNALBAN')
home = home.replace('vagy ülj le egy kávé mellé.', 'vagy ülj le egy kávé mellé péksütizni.')
home = home.replace('Kedd–szombat', 'Kedd–Szombat').replace('Vasárnap–hétfő', 'Vasárnap–Hétfő')
home = re.sub(r'(<span class="eyebrow">)0[1-5] / ', r'\1', home)
home = home.replace('<div class="steps"><span><b>01</b> Válassz</span><span><b>02</b> Írd meg a részleteket</span><span><b>03</b> Várd a visszajelzésünket</span></div>', '<ol class="steps" aria-label="Az előrendelés menete"><li><b>1</b><span>Válassz</span></li><li><b>2</b><span>Írd meg a részleteket</span></li><li><b>3</b><span>Várd a visszajelzésünket</span></li></ol>')
home = home.replace('>Előrendelést indítok <span', '>Előrendelek <span')
home = home.replace('<div><span>Kedd–péntek</span><strong>7:00–14:00</strong></div><div><span>Szombat</span><strong>7:00–14:00</strong></div>', '<div><span>Kedd–Szombat</span><strong>7:00–14:00</strong></div>')
home = home.replace('<div class="about-photo"><img src="assets/hands.webp" alt="Lisztes kézzel formált tészta"', '<div class="about-photo"><img src="assets/oven-bread.webp" alt="Frissen sült kovászos kenyerek a kemence előtt"')
start, end = chrome(dict(slug="index", title="Kovászos pékség és reggeliző Pécsen", description="Friss kovászos kenyér, péksütemény és reggeli Pécs belvárosában. Egész kenyér és torta előrendelhető."))
(SITE / "index.html").write_text(start + without_button_arrows(home) + end, encoding="utf-8")

def hero(eyebrow, title, lead, image=None, alt=""):
    media = f'<div class="inner-hero-image"><img src="assets/{image}.webp" alt="{alt}"></div>' if image else ''
    return f'<section class="inner-hero"><div><span class="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{lead}</p></div>{media}</section>'

def end_cta(title, href, label):
    return f'<section class="final-cta"><span class="eyebrow">HAJNAL · PÉCS</span><h2>{title}</h2><a class="button" href="{href}">{label} <span aria-hidden="true">↗</span></a></section>'

catalog = hero('A KIS PÉKSÉG A SARKON / KÍNÁLAT', 'Amit reggelente kisütünk.', 'Kenyér a hétköznapokra, péksütemény a reggeli kávé mellé, torta az ünnepre. A napi készlet változik, a kedvencek délre elfogyhatnak.')
catalog += '''<section class="content-section catalog-block"><div class="catalog-heading"><span class="eyebrow">01 / KENYEREK</span><h2>Kovászos kenyerek</h2><p>Egész kenyérre legalább egy nappal korábban előrendelést is felveszünk.</p></div><div class="catalog-grid"><article><span class="stamp">ELŐRENDELHETŐ</span><h3>Klasszikus fehér kovászos</h3><p>Ropogós héj, puha belső. Reggelire és a hétköznapokra.</p></article><article><span class="stamp">ELŐRENDELHETŐ</span><h3>Magvas kovászos</h3><p>Telt íz, pirított magok, tartalmas szeletek.</p></article><article><span class="stamp">NAPI KÍNÁLAT</span><h3>Az aznapi különlegesség</h3><p>A pultnál derül ki, mi került még a kemencébe.</p></article></div></section>'''
