catalog += end_cta('Biztosra mennél?', 'elorendeles.html', 'Előrendelést indítok')
catalog = catalog.replace('Egész kenyérre legalább egy nappal korábban előrendelést is felveszünk.</p></div><div class="catalog-grid">', 'Egész kenyérre legalább egy nappal korábban előrendelést is felveszünk.</p><a class="button button-secondary" href="elorendeles.html?termek=kenyer">Kenyeret rendelek</a></div><div class="catalog-grid">')
catalog = catalog.replace('<div class="catalog-heading">', '<div class="catalog-intro"><div class="catalog-heading">', 1)
catalog = catalog.replace('Kenyeret rendelek</a></div><div class="catalog-grid">', 'Kenyeret rendelek</a></div><div class="catalog-bread-photo"><img src="assets/catalog_bread.webp" alt="Frissen sült kovászos kenyér" loading="lazy"></div></div><div class="catalog-grid">', 1)
page('kinalat', 'Kínálat', 'Kovászos kenyerek, péksütemények, reggeli és előrendelhető torták a Hajnal pécsi pékségében.', catalog)

